import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLDiv} from '@github-ui/safe-html/VerifiedHTML'

import styles from './SimpleCodeListing.module.css'

interface SimpleCodeListingProps {
  lineNumbers: number[]
  lines: SafeHTMLString[]
  trimLineBeginnings?: boolean
}

export function SimpleCodeListing({lineNumbers, lines, trimLineBeginnings}: SimpleCodeListingProps) {
  return (
    <div className={styles.SimpleCodeListing}>
      <table
        style={{
          fontSize: '12px',
          fontFamily: 'var(--fontStack-monospace)',
          overflowX: 'auto',
        }}
      >
        {lineNumbers.map((num, i) => (
          <tr key={`line-row-${num}`}>
            <td key={num}>{num}</td>
            <td style={{whiteSpace: 'pre', paddingLeft: '16px'}}>
              <VerifiedHTMLDiv
                // eslint-disable-next-line @eslint-react/no-array-index-key
                key={`line-${i}`}
                html={
                  trimLineBeginnings
                    ? /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- HTML is sanitized server-side. TODO: Move type assertion to data ingress point. */
                      trimLineBeginning(lines[i] ?? ('' as SafeHTMLString))
                    : /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- HTML is sanitized server-side. TODO: Move type assertion to data ingress point. */
                      lines[i] || ('\n' as SafeHTMLString)
                }
              />
            </td>
          </tr>
        ))}
      </table>
    </div>
  )
}

function trimLineBeginning(str: SafeHTMLString): SafeHTMLString {
  /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Composed from sanitized input. See: str param */
  return str.trimStart() as SafeHTMLString
}
